"""Lightweight Chrome DevTools Protocol client."""
import json, sys, time
import websocket
import urllib.request

CDP_HOST = "http://localhost:1337"

def get_tabs():
    return json.loads(urllib.request.urlopen(f"{CDP_HOST}/json").read())

def get_first_page():
    for t in get_tabs():
        if t.get("type") == "page":
            return t
    raise RuntimeError("no page tab")

class CDP:
    def __init__(self, ws_url):
        self.ws = websocket.create_connection(ws_url, timeout=30)
        self.id = 0
    def send(self, method, params=None):
        self.id += 1
        msg = {"id": self.id, "method": method}
        if params:
            msg["params"] = params
        self.ws.send(json.dumps(msg))
        while True:
            r = json.loads(self.ws.recv())
            if r.get("id") == self.id:
                if "error" in r:
                    raise RuntimeError(f"{method}: {r['error']}")
                return r.get("result", {})
    def eval(self, expr, await_promise=False, return_by_value=True):
        r = self.send("Runtime.evaluate", {
            "expression": expr,
            "returnByValue": return_by_value,
            "awaitPromise": await_promise,
        })
        if "exceptionDetails" in r:
            raise RuntimeError(f"JS exception: {r['exceptionDetails']}")
        return r.get("result", {}).get("value")
    def navigate(self, url):
        self.send("Page.enable")
        self.send("Page.navigate", {"url": url})
    def wait_load(self, timeout=20):
        end = time.time() + timeout
        while time.time() < end:
            ready = self.eval("document.readyState")
            if ready == "complete":
                return
            time.sleep(0.3)
        raise TimeoutError("page load")
    def close(self):
        try: self.ws.close()
        except: pass

def connect():
    page = get_first_page()
    return CDP(page["webSocketDebuggerUrl"]), page

if __name__ == "__main__":
    c, page = connect()
    print("Title:", c.eval("document.title"))
    print("URL:", c.eval("location.href"))

