import sys, time, json
sys.path.insert(0, '/tmp')
from cdp import connect

c, page = connect()

# Use native input value setter to trigger React/MS event handlers
js = '''(() => {
  const setInput = (el, value) => {
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement.prototype : HTMLInputElement.prototype;
    const setter = Object.getOwnPropertyDescriptor(proto, 'value').set;
    setter.call(el, value);
    el.dispatchEvent(new Event('input', {bubbles: true}));
    el.dispatchEvent(new Event('change', {bubbles: true}));
    el.dispatchEvent(new Event('blur', {bubbles: true}));
  };
  const name = document.querySelector('input[placeholder="First and last name *"]');
  const email = document.querySelector('input[placeholder="Email *"]');
  if (!name || !email) return 'inputs not found: name=' + !!name + ' email=' + !!email;
  name.focus();
  setInput(name, 'James Smith');
  email.focus();
  setInput(email, 'james.smith@gmail.com');
  return {name: name.value, email: email.value};
})()'''
print(c.eval(js))
